public static List<JSONObject> createAlarmConfigPidList(AlarmConfigInfo alarmConfigInfo) {
    LogUtils.d("<literal omitted>", "<literal omitted>" + alarmConfigInfo + "<literal omitted>");
    if (alarmConfigInfo == null) {
        return null;
    }
    ArrayList arrayList = new ArrayList();
    int i = alarmConfigInfo.isbMotionAlarmSwitch() ? IoTDevAbilityDefines._abl_alert_event_bmcp32.ABL_ALERT_DETECT_MOTION : 0;
    ArrayList arrayList2 = new ArrayList();
    if (alarmConfigInfo.getCustomAlarmTimeNumber() == 0 || (alarmConfigInfo.getCustomAlarmTimeNumber() == 1 && alarmConfigInfo.getServerAlarmSwitch1() == 0 && alarmConfigInfo.getServerAlarmSwitch2() == 0 && alarmConfigInfo.getServerAlarmSwitch3() == 0)) {
        AlarmTimeSetJsonParse.DayBean.ScheBean scheBean = new AlarmTimeSetJsonParse.DayBean.ScheBean();
        scheBean.setEnable(true);
        scheBean.setMode(i);
        scheBean.setS_time("0:0:0");
        scheBean.setE_time("23:59:59");
        arrayList2.add(scheBean);
    } else {
        for (int i2 = 0; i2 < alarmConfigInfo.getCustomAlarmTimeNumber() && i2 < 3; i2++) {
            if (i2 == 0) {
                AlarmTimeSetJsonParse.DayBean.ScheBean scheBean2 = new AlarmTimeSetJsonParse.DayBean.ScheBean();
                scheBean2.setEnable(alarmConfigInfo.getServerAlarmSwitch1() == 1);
                scheBean2.setMode(i);
                scheBean2.setS_time(alarmConfigInfo.getStarthour1() + ":" + alarmConfigInfo.getStartmin1() + ":" + alarmConfigInfo.getStartsec1());
                scheBean2.setE_time(alarmConfigInfo.getEndhour1() + ":" + alarmConfigInfo.getEndmin1() + ":" + alarmConfigInfo.getEndsec1());
                arrayList2.add(scheBean2);
            } else if (i2 == 1) {
                AlarmTimeSetJsonParse.DayBean.ScheBean scheBean3 = new AlarmTimeSetJsonParse.DayBean.ScheBean();
                scheBean3.setEnable(alarmConfigInfo.getServerAlarmSwitch2() == 1);
                scheBean3.setMode(i);
                scheBean3.setS_time(alarmConfigInfo.getStarthour2() + ":" + alarmConfigInfo.getStartmin2() + ":" + alarmConfigInfo.getStartsec2());
                scheBean3.setE_time(alarmConfigInfo.getEndhour2() + ":" + alarmConfigInfo.getEndmin2() + ":" + alarmConfigInfo.getEndsec2());
                arrayList2.add(scheBean3);
            } else if (i2 == 2) {
                AlarmTimeSetJsonParse.DayBean.ScheBean scheBean4 = new AlarmTimeSetJsonParse.DayBean.ScheBean();
                scheBean4.setEnable(alarmConfigInfo.getServerAlarmSwitch3() == 1);
                scheBean4.setMode(i);
                scheBean4.setS_time(alarmConfigInfo.getStarthour3() + ":" + alarmConfigInfo.getStartmin3() + ":" + alarmConfigInfo.getStartsec3());
                scheBean4.setE_time(alarmConfigInfo.getEndhour3() + ":" + alarmConfigInfo.getEndmin3() + ":" + alarmConfigInfo.getEndsec3());
                arrayList2.add(scheBean4);
            }
        }
    }
    AlarmTimeSetJsonParse.DayBean dayBean = new AlarmTimeSetJsonParse.DayBean();
    dayBean.setCnt(alarmConfigInfo.getCustomAlarmTimeNumber() != 0 ? alarmConfigInfo.getCustomAlarmTimeNumber() : 1);
    dayBean.setSche(arrayList2);
    AlarmTimeSetJsonParse alarmTimeSetJsonParse = new AlarmTimeSetJsonParse();
    alarmTimeSetJsonParse.setMon(dayBean);
    alarmTimeSetJsonParse.setTue(dayBean);
    alarmTimeSetJsonParse.setWed(dayBean);
    alarmTimeSetJsonParse.setThu(dayBean);
    alarmTimeSetJsonParse.setFri(dayBean);
    alarmTimeSetJsonParse.setSat(dayBean);
    alarmTimeSetJsonParse.setSun(dayBean);
    JSONObject jSONObject = new JSONObject();
    try {
        jSONObject = new JSONObject(new Gson().toJson(alarmTimeSetJsonParse));
    } catch (JSONException e) {
        e.printStackTrace();
    }
    AlarmAreaJsonParse alarmAreaJsonParse = new AlarmAreaJsonParse();
    alarmAreaJsonParse.setAlarmAreaRowCnt(alarmConfigInfo.getAlarmrows());
    alarmAreaJsonParse.setAlarmAreaLineCnt(alarmConfigInfo.getAlarmcolumns());
    alarmAreaJsonParse.setAlarmArea(alarmConfigInfo.getAlarmAreaList());
    JSONObject jSONObject2 = new JSONObject();
    try {
        jSONObject2 = new JSONObject(new Gson().toJson(alarmAreaJsonParse));
    } catch (JSONException e2) {
        e2.printStackTrace();
    }
    if (alarmConfigInfo.isbMainAlarmSwitch()) {
        arrayList.add(createJSONObjectValueJsonObj(Protocol.DPID_ALARM_MT_AREA, jSONObject2));
        arrayList.add(createJSONObjectValueJsonObj(Protocol.DPID_ALARM_TIMER_INFO, jSONObject));
        arrayList.add(createBooleanValueJsonObj(Protocol.DPID_ALARM_MT_SW, alarmConfigInfo.isbMotionAlarmSwitch()));
        if (alarmConfigInfo.isHasVoicePromptsConfig()) {
            arrayList.add(createBooleanValueJsonObj(Protocol.DPID_ALARM_SOUND_SW, alarmConfigInfo.isbAlarmVoiceSwitch()));
        }
        arrayList.add(createBooleanValueJsonObj(Protocol.DPID_ALARM_MAIN_SW, alarmConfigInfo.isbMainAlarmSwitch()));
    } else {
        arrayList.add(createBooleanValueJsonObj(Protocol.DPID_ALARM_MAIN_SW, alarmConfigInfo.isbMainAlarmSwitch()));
        arrayList.add(createBooleanValueJsonObj(Protocol.DPID_ALARM_MT_SW, alarmConfigInfo.isbMotionAlarmSwitch()));
        if (alarmConfigInfo.isHasVoicePromptsConfig()) {
            arrayList.add(createBooleanValueJsonObj(Protocol.DPID_ALARM_SOUND_SW, alarmConfigInfo.isbAlarmVoiceSwitch()));
        }
        arrayList.add(createJSONObjectValueJsonObj(Protocol.DPID_ALARM_MT_AREA, jSONObject2));
        arrayList.add(createJSONObjectValueJsonObj(Protocol.DPID_ALARM_TIMER_INFO, jSONObject));
    }
    LogUtils.d("<literal omitted>", "<literal omitted>" + arrayList);
    return arrayList;
}
